// Runs the command line it is handed through the spawn builtin `how` names,
// one line of answer each: the status, and for a captured run the bytes the
// child printed. `to` sends stdout to a file in the working directory, which
// this package has no `fs.write` for, so under `--sandbox` that child dies
// before its exec. Nothing the compiler can check, so the sandbox holds it to
// the grant's programs.
const reaped = (pid: i32): i32 => {
  if (pid <= 0) {
    return pid;
  }
  return waitPid(pid, 0)[1];
};

export const runProgram = (how: string, argv: string[]): string => {
  const none: u8[] = [];
  const out: u8[] = [];
  const err: u8[] = [];
  if (how === "sync") {
    return `${spawnSync(argv)}`;
  }
  if (how === "to") {
    return `${spawnSyncTo(argv, "refused.txt", "")}`;
  }
  if (how === "piped") {
    return `${spawnPiped(argv, none, out, err)} ${out.length}`;
  }
  if (how === "within") {
    return `${spawnPipedWithin(argv, none, out, err, 30000)} ${out.length}`;
  }
  if (how === "fds") {
    return `${reaped(spawnWithFds(argv, [1]))}`;
  }
  return `${reaped(spawn(argv))}`;
};
